export default async ({ page, toolURL, screenshot, assert }) => {
  page.setDefaultTimeout(30000)
  const T = ORACLE.meta.tabs
  const onTab = async (t) => { await page.click('#tab-' + t); await page.waitForFunction((k) => !document.getElementById('pane-' + k).hidden, t) }
  const buf = (b64) => Buffer.from(b64, 'base64')
  const disp = (sel) => page.$eval(sel, (e) => getComputedStyle(e).display)
  // 按格式显隐的是外层 [data-for] 字段：断它的计算样式（控件自己的 display 不会因祖先被藏而变成 none）
  const fieldDisp = (sel) => page.$eval(sel, (e) => getComputedStyle(e.closest('[data-for]')).display)
  const txt = (sel) => page.$eval(sel, (e) => e.textContent.trim())
  const seq = () => page.$eval('#gs-result', (e) => +(e.getAttribute('data-seq') || 0))
  let encodes = 0
  // 正向等待：结果卡的序号前进、且这一份的质量指标也算完（别等「文字里出现 dB」—— 旧结果的文字会让条件瞬间成立）
  async function run(btn) {
    const s0 = await seq()
    await page.click(btn)
    await page.waitForFunction((s) => {
      const r = document.getElementById('gs-result'), st = document.getElementById('gs-status').textContent
      return /出错|超出/.test(st) || (+(r.getAttribute('data-qseq') || 0) > s && r.getAttribute('data-qseq') === r.getAttribute('data-seq'))
    }, s0, { timeout: 120000 })
    const st = await txt('#gs-status')
    assert(!/出错/.test(st), `${btn} 状态：${st}`)
    encodes++
    return st
  }
  async function setVal(sel, v) {
    await page.$eval(sel, (e, val) => { e.value = val; e.dispatchEvent(new Event('change', { bubbles: true })) }, String(v))
  }
  // 用浏览器原生解码器把最后一次输出解回来：对编码器自己的「预期显示帧」逐像素比；
  // full=true 时再按时间把每个基础帧对上它显示时的输出帧，断「逐通道误差 ≤ 容差」（无损真彩模式的容差语义）
  const verify = (fmt, full) => page.evaluate(async ([fmt, full]) => {
    const L = GSApp.last(), mime = { gif: 'image/gif', apng: 'image/png', webp: 'image/webp' }[fmt]
    const dec = new ImageDecoder({ data: L.bytes, type: mime })
    await dec.tracks.ready
    const tr = dec.tracks.selectedTrack, n = tr.frameCount
    const c = document.createElement('canvas'); c.width = L.W; c.height = L.H
    const g = c.getContext('2d', { willReadFrequently: true })
    const out = []; const durs = []
    let badPx = 0, maxD = 0
    for (let j = 0; j < n; j++) {
      const r = await dec.decode({ frameIndex: j })
      g.clearRect(0, 0, L.W, L.H); g.drawImage(r.image, 0, 0); durs.push(r.image.duration); r.image.close()
      const d = g.getImageData(0, 0, L.W, L.H).data
      out.push(d)
      const want = L.job.intended[j]
      if (!want) continue
      for (let i = 0; i < d.length; i += 4) {
        if (d[i + 3] === 0 && want[i + 3] === 0) continue
        const dd = Math.max(Math.abs(d[i] - want[i]), Math.abs(d[i + 1] - want[i + 1]), Math.abs(d[i + 2] - want[i + 2]), Math.abs(d[i + 3] - want[i + 3]))
        if (dd) badPx++
        if (dd > maxD) maxD = dd
      }
    }
    dec.close()
    let maxVsBase = -1, baseChecked = 0
    if (full) {
      maxVsBase = 0
      for (let k = 0; k < L.frames.length; k++) {
        let j = 0
        for (let q = 0; q < L.job.out.length; q++) if (L.job.out[q].src <= k) j = q
        const a = out[j], b = L.frames[k].data
        for (let i = 0; i < a.length; i += 4) {
          if (a[i + 3] === 0 && b[i + 3] === 0) continue
          maxVsBase = Math.max(maxVsBase, Math.abs(a[i] - b[i]), Math.abs(a[i + 1] - b[i + 1]), Math.abs(a[i + 2] - b[i + 2]), Math.abs(a[i + 3] - b[i + 3]))
        }
        baseChecked++
      }
    }
    // 自家 GIF 解码器（第二个独立解码器）
    let ownBad = -1, eoiBad = -1
    if (fmt === 'gif') {
      const gg = GS.decodeGIF(L.bytes); ownBad = 0
      eoiBad = gg.frames.filter((f) => f.lzwEnd !== 'eoi' || f.trailing !== 0).length
      gg.decodedFrames.forEach((f, j) => { for (let i = 0; i < f.data.length; i++) if (f.data[i] !== out[j][i] && !(f.data[i - (i % 4) + 3] === 0 && out[j][i - (i % 4) + 3] === 0)) ownBad++ })
    }
    return { n, out: L.job.out.length, rep: tr.repetitionCount === Infinity ? -1 : tr.repetitionCount, badPx, maxD, durs,
      delays: L.job.out.map((f) => f.delay), cs: fmt === 'gif' ? Array.from(GS.centis(L.job.out.map((f) => f.delay))) : null,
      bytes: L.bytes.length, W: L.W, H: L.H, maxVsBase, baseChecked, ownBad, eoiBad, keep: L.keep, fuzz: L.P.fuzz, base: L.frames.length }
  }, [fmt, !!full])

  await page.goto(toolURL)

  // ══ 0 结构 ══
  const back = await page.$eval('a.gs-back', (a) => [a.textContent.trim(), a.getAttribute('href')])
  assert(back[0] === '← 返回工具集' && back[1] === '../../', '返回链接：' + back.join(' '))
  assert((await page.title()).includes('动图工坊'), '标题')
  assert(await page.$eval('#gs-encode', (b) => b.disabled), '没有素材时「生成」应禁用')

  // ══ 1 引擎页内自检：LZW 往返（含把 4096 码表填满多次的噪声流）、≤K 色无损、延迟取整 ══
  const eng = await page.evaluate(() => {
    let ok = 0, tot = 0
    let seed = 12345
    const rnd = () => (seed = (Math.imul(seed, 1103515245) + 12345) >>> 0) / 4294967296
    for (const [minCode, len, alpha] of [[2, 1, 4], [2, 5000, 3], [3, 7000, 8], [4, 20000, 16], [5, 3000, 2], [8, 120000, 256], [8, 65536, 7], [6, 1, 64]]) {
      const idx = new Uint8Array(len)
      for (let i = 0; i < len; i++) idx[i] = alpha === 7 ? (i >> 9) % 7 : Math.floor(rnd() * alpha) % (1 << minCode)
      const enc = GS.lzwEncode(idx, minCode)
      const parts = []; let p = 1
      while (enc[p]) { parts.push(...enc.subarray(p + 1, p + 1 + enc[p])); p += 1 + enc[p] }
      const outp = new Uint8Array(len), got = GS.lzwDecode(Uint8Array.from(parts), minCode, outp)
      tot++; if (got === len && outp.every((v, i) => v === idx[i])) ok++
    }
    // 37 种颜色 → 三种量化都应原样保留（不超过上限就不该丢色）
    const h = new GS.Hist(); const cols = []
    for (let i = 0; i < 37; i++) { const c = [(i * 53) % 256, (i * 97) % 256, (i * 29) % 256]; cols.push(c.join()); h.add(c[0], c[1], c[2], 1 + i) }
    const exact = ['wu', 'median', 'octree'].every((m) => { const pal = GS.quantize(h, 64, m, 0); const s = new Set(); for (let i = 0; i < pal.length; i += 3) s.add(pal[i] + ',' + pal[i + 1] + ',' + pal[i + 2]); return s.size === 37 && cols.every((c) => s.has(c)) })
    // 收尾：每条码流读满像素后紧跟 EOI、且没有多余字节（宽松解码器看不出收尾错，必须单独断）
    let strictOk = 0, strictN = 0
    for (const mc of [2, 3, 4, 8]) for (let len = 1; len <= 260; len++) {
      const idx = new Uint8Array(len)
      for (let i = 0; i < len; i++) idx[i] = Math.floor(rnd() * Math.min(256, 1 << mc))
      const enc = GS.lzwEncode(idx, mc), parts = []; let p = 1
      while (enc[p]) { parts.push(...enc.subarray(p + 1, p + 1 + enc[p])); p += 1 + enc[p] }
      const o2 = new Uint8Array(len), info = {}, got = GS.lzwDecode(Uint8Array.from(parts), mc, o2, info)
      strictN++; if (got === len && info.end === 'eoi' && info.trailingBytes === 0 && o2.every((v, i) => v === idx[i])) strictOk++
    }
    // 同一个 5 位格里的近色（只差 1）：超出上限前必须原样保留 —— Wu 的 33³ 直方图分不开它们，只能靠「≤K 直接用原色」
    const h2 = new GS.Hist(); const tight = []
    for (let i = 0; i < 40; i++) { const c = [96 + (i % 4), 40 + 8 * Math.floor(i / 4), 200]; tight.push(c.join()); h2.add(c[0], c[1], c[2], 1) }
    const pal2 = GS.quantize(h2, 64, 'wu', 0), s2 = new Set()
    for (let i = 0; i < pal2.length; i += 3) s2.add(pal2[i] + ',' + pal2[i + 1] + ',' + pal2[i + 2])
    const tightExact = s2.size === 40 && tight.every((c) => s2.has(c))
    const ms = [66.6667, 66.6667, 66.6667, 33.3333, 15, 15, 15, 1000]
    const cs = GS.centis(ms)
    const total = ms.reduce((a, b) => a + b, 0) / 10, sum = cs.reduce((a, b) => a + b, 0)
    return { ok, tot, exact, csMin: Math.min(...cs), csErr: Math.abs(sum - total), strictOk, strictN, tightExact }
  })
  assert(eng.strictOk === eng.strictN && eng.strictN === 1040, `LZW 收尾（EOI 紧跟最后一个像素、无多余字节）${eng.strictOk}/${eng.strictN}`)
  assert(eng.tightExact, '同一 5 位格里的 40 种近色应原样保留')
  assert(eng.ok === eng.tot, `LZW 往返 ${eng.ok}/${eng.tot}`)
  assert(eng.exact, '≤K 色时三种量化都应无损')
  assert(eng.csMin >= 2, 'GIF 延迟最短 2 cs')
  assert(eng.csErr <= 4.0001, 'GIF 延迟误差扩散：总时长误差应有界（含 15 ms 帧被抬到 20 ms 的 3×0.5 cs），实得 ' + eng.csErr)

  // ══ 2 示例「黄昏山谷」→ GIF：浏览器解码 = 编码器预期（逐像素），自家解码器 = 浏览器 ══
  await page.click('#gs-demo-dusk')
  await page.waitForFunction(() => !document.querySelector('#gs-encode').disabled)
  assert(await disp('#gs-drop') === 'none', '载入素材后拖放区应真的被藏起来（计算样式）')
  assert(await disp('#gs-cancel') === 'none', '空闲时「取消」应藏起来')
  const srcInfo = await txt('#gs-src-info')
  assert(/480 × 270/.test(srcInfo) && /45 帧/.test(srcInfo), '素材信息：' + srcInfo)
  assert(/输出 480 × 270 · 约 45 帧/.test(await txt('#gs-outdim')), '输出尺寸提示：' + await txt('#gs-outdim'))
  await run('#gs-encode')
  const g1 = await verify('gif')
  assert(g1.keep, '小素材应保留预期帧')
  assert(g1.n === g1.out && g1.n === 45, `GIF 帧数 ${g1.n} / ${g1.out}`)
  assert(g1.badPx === 0, `Chromium 解码 vs 编码器预期：${g1.badPx} 个像素不同（最大差 ${g1.maxD}）`)
  assert(g1.ownBad === 0, `自家 GIF 解码器 vs Chromium：${g1.ownBad} 个通道不同`)
  assert(g1.eoiBad === 0, `每帧 LZW 码流都应以 EOI 收尾、无多余字节：${g1.eoiBad} 帧不合格`)
  assert(g1.durs.every((d, j) => d === g1.cs[j] * 10000), 'Chromium 读到的每帧时长应等于写进去的 cs × 10 ms')
  assert(g1.rep === -1, '默认无限循环：repetitionCount 应为 Infinity，实得 ' + g1.rep)
  const sizeTxt = await txt('#gs-res-size')
  assert(sizeTxt === await page.evaluate(() => GS.fmtBytes(GSApp.last().bytes.length)), '体积显示：' + sizeTxt)
  const dlLen = await page.evaluate(async () => (await (await fetch(document.getElementById('gs-download').href)).arrayBuffer()).byteLength)
  assert(dlLen === g1.bytes, `下载链接的字节数 ${dlLen} 应等于编码结果 ${g1.bytes}`)
  assert((await page.$eval('#gs-download', (a) => a.download)) === '示例-黄昏山谷-480x270.gif', '下载文件名')
  // PSNR：测试自己按「浏览器解码帧 vs 源帧」算一遍，和页面显示的对上（页面抽查 ≤48 帧，这里同样的抽法）
  const psnr = await page.evaluate(async () => {
    const L = GSApp.last(), dec = new ImageDecoder({ data: L.bytes, type: 'image/gif' }); await dec.tracks.ready
    const c = document.createElement('canvas'); c.width = L.W; c.height = L.H; const g = c.getContext('2d', { willReadFrequently: true })
    const n = L.job.out.length, step = Math.max(1, Math.ceil(n / 48)); let s = 0, k = 0
    for (let j = 0; j < n; j += step) {
      const r = await dec.decode({ frameIndex: j }); g.clearRect(0, 0, L.W, L.H); g.drawImage(r.image, 0, 0); r.image.close()
      const a = g.getImageData(0, 0, L.W, L.H).data, b = L.frames[L.job.out[j].src].data; let e = 0
      for (let i = 0; i < a.length; i += 4) { const dr = (a[i] * a[i + 3] - b[i] * b[i + 3]) / 255, dg = (a[i + 1] * a[i + 3] - b[i + 1] * b[i + 3]) / 255, db = (a[i + 2] * a[i + 3] - b[i + 2] * b[i + 3]) / 255, da = a[i + 3] - b[i + 3]; e += dr * dr + dg * dg + db * db + da * da }
      s += 10 * Math.log10(65025 / (e / (a.length))); k++
    }
    dec.close()
    return { mine: s / k, shown: +document.getElementById('gs-m-psnr').getAttribute('data-psnr'), text: document.getElementById('gs-m-psnr').textContent }
  })
  assert(Math.abs(psnr.mine - psnr.shown) < 1e-6 && psnr.text === psnr.shown.toFixed(1) + ' dB', `PSNR 显示 ${psnr.text}，测试复算 ${psnr.mine}`)
  assert(psnr.mine > 38, 'FS 抖动 + 255 色的山谷动画 PSNR 应 > 38 dB，实得 ' + psnr.mine)
  // 每帧字节图：柱子个数 = 输出帧数；柱高之比 = 字节数之比（几何断言，不只断数字）
  const bars = await page.evaluate(() => {
    const L = GSApp.last(), rects = [...document.querySelectorAll('#gs-res-chart rect[data-i]')]
    const h = rects.map((r) => r.getBoundingClientRect().height)
    const i1 = 1 + L.sizes.slice(1).indexOf(Math.max(...L.sizes.slice(1)))
    return { n: rects.length, out: L.sizes.length, h0: h[0], hMaxRest: Math.max(...h.slice(1)), ratio: h[i1] / h[0], want: L.sizes[i1] / L.sizes[0] }
  })
  assert(bars.n === bars.out && bars.n === 45, `柱子 ${bars.n} 根，输出 ${bars.out} 帧`)
  assert(bars.h0 > bars.hMaxRest, '第 1 帧要画满整幅，柱子应最高')
  assert(Math.abs(bars.ratio - bars.want) < 0.02, `柱高之比 ${bars.ratio.toFixed(4)} 应等于字节之比 ${bars.want.toFixed(4)}`)
  // 帧间优化真的省字节：关掉它再编一次，体积应明显更大
  await page.click('#gs-optimize')
  await run('#gs-encode')
  const noOpt = await page.evaluate(() => ({ bytes: GSApp.last().bytes.length, rects: GSApp.last().job.out.filter((f) => f.w * f.h < GSApp.last().W * GSApp.last().H).length }))
  await page.click('#gs-optimize')
  assert(noOpt.rects === 0 && noOpt.bytes > g1.bytes * 1.3, `关掉帧间优化：${noOpt.bytes} 字节（开着是 ${g1.bytes}），裁剪帧 ${noOpt.rects}`)
  assert(await disp('#gs-cmpwrap') === 'none', '输出视图下对比区应藏起来')

  // ══ 3 APNG（调色板 / 真彩）与 WebP（无损 / 有损），循环「播放 3 次」 ══
  await page.selectOption('#gs-loop', '1')
  await run('#gs-encode')
  const g0 = await verify('gif')
  assert(g0.rep === 0 && (await page.evaluate(() => GS.parseGIF(GSApp.last().bytes).loop)) === null, '播放 1 次 → 不写 NETSCAPE 扩展 → repetitionCount 应为 0，实得 ' + g0.rep)
  await page.selectOption('#gs-loop', '3')
  await run('#gs-encode')
  const g3 = await verify('gif')
  assert(g3.rep === 2 && g3.badPx === 0 && (await page.evaluate(() => GS.parseGIF(GSApp.last().bytes).loop)) === 2, '播放 3 次 → NETSCAPE 字段写 2 → repetitionCount 应为 2，实得 ' + g3.rep)
  await page.click('#gs-fmt button[data-fmt="apng"]')
  assert(await fieldDisp('#gs-apng-mode') !== 'none' && await fieldDisp('#gs-webp-q') === 'none', 'APNG 时显示 APNG 选项、藏 WebP 质量')
  await run('#gs-encode')
  const a1 = await verify('apng')
  assert(a1.badPx === 0 && a1.n === a1.out, `调色板 APNG：${a1.badPx} 个像素不同，${a1.n}/${a1.out} 帧`)
  assert(a1.rep === 2, '播放 3 次 → APNG num_plays=3 → repetitionCount 应为 2，实得 ' + a1.rep)
  assert(a1.durs.every((d, j) => Math.abs(d - Math.round(a1.delays[j]) * 1000) <= 1), 'APNG 帧时长（毫秒精度）')
  await page.selectOption('#gs-apng-mode', 'rgba')
  assert(await fieldDisp('#gs-colors') === 'none', '真彩 APNG 不该显示颜色数')
  await run('#gs-encode')
  const a2 = await verify('apng', true)
  assert(a2.badPx === 0, `真彩 APNG 应逐像素无损：${a2.badPx} 个像素不同`)
  assert(a2.baseChecked === 45 && a2.maxVsBase <= a2.fuzz, `容差语义：每个源帧显示时与源的逐通道误差 ${a2.maxVsBase} 应 ≤ 容差 ${a2.fuzz}`)
  await page.click('#gs-fmt button[data-fmt="webp"]')
  await setVal('#gs-webp-q', 100)
  await run('#gs-encode')
  const w1 = await verify('webp', true)
  assert(w1.badPx === 0 && w1.n === w1.out, `无损 WebP（VP8L）应逐像素一致：${w1.badPx} 个像素不同`)
  assert(w1.rep === 2, '播放 3 次 → WebP loop=3 → repetitionCount 应为 2，实得 ' + w1.rep)
  assert(w1.maxVsBase <= w1.fuzz, `WebP 容差语义：${w1.maxVsBase} ≤ ${w1.fuzz}`)
  const wInfo = await page.evaluate(() => { const p = GS.parseWebP(GSApp.last().bytes); return { anim: p.animated, n: p.frames.length, even: p.frames.every((f) => f.x % 2 === 0 && f.y % 2 === 0), loop: p.loop } })
  assert(wInfo.anim && wInfo.n === w1.out && wInfo.even && wInfo.loop === 3, 'WebP 结构：' + JSON.stringify(wInfo))
  await setVal('#gs-webp-q', 70)
  await run('#gs-encode')
  const w2 = await verify('webp')
  assert(w2.n === w2.out && w2.bytes < w1.bytes, `有损 WebP 应更小：${w2.bytes} vs 无损 ${w1.bytes}`)
  const wp = +(await page.$eval('#gs-m-psnr', (e) => e.getAttribute('data-psnr')))
  assert(wp > 30 && wp < 60, '有损 WebP 的 PSNR 应在 30–60 dB，实得 ' + wp)
  await page.selectOption('#gs-loop', '0')
  await page.click('#gs-fmt button[data-fmt="gif"]')

  // ══ 4 输入校验与剪辑 ══
  await setVal('#gs-colors', '')
  assert(await page.$eval('#gs-colors', (e) => e.value) === '256' && /需要一个数字/.test(await txt('#gs-status')), '颜色数填空应恢复原值并提示')
  await setVal('#gs-colors', 999)
  assert(await page.$eval('#gs-colors', (e) => e.value) === '256', '颜色数超上限应夹到 256')
  await setVal('#gs-t1', 0)
  assert(/终点必须比起点晚/.test(await txt('#gs-status')) && await page.$eval('#gs-t1', (e) => e.value) === '3', '终点 ≤ 起点应拒绝')
  await setVal('#gs-t0', 1); await setVal('#gs-t1', 2)
  assert((await page.evaluate(() => GSApp.plan().length)) === 15, '截 1–2 秒、保持源帧（15 fps）应得 15 帧')
  await page.selectOption('#gs-dir', 'pingpong')
  assert((await page.evaluate(() => GSApp.plan().length)) === 28, '往返：15 + 13 = 28 帧（掉头处不重复）')
  await page.selectOption('#gs-dir', 'forward')
  await setVal('#gs-t0', 0); await setVal('#gs-t1', 3)
  // 裁剪：1:1 比例 → 拖右下角缩小，宽高保持相等；键盘方向键移动 2 像素
  await page.click('#gs-view-src')
  await page.selectOption('#gs-ratio', '1')
  const c0 = await page.evaluate(() => GSApp.crop())
  assert(c0.w === 270 && c0.h === 270 && c0.x === 105, '1:1 应取居中最大正方形：' + JSON.stringify(c0))
  const hb = await page.$eval('#gs-cropbox .gs-h-se', (e) => { const r = e.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height / 2 } })
  const kk = await page.evaluate(() => { const cv = document.getElementById('gs-src-canvas'), r = cv.getBoundingClientRect(); return Math.min(r.width / cv.width, r.height / cv.height) * cv.width / GSApp.src().w })
  await page.mouse.move(hb.x, hb.y); await page.mouse.down(); await page.mouse.move(hb.x - 60 * kk, hb.y - 60 * kk, { steps: 4 }); await page.mouse.up()
  const c1 = await page.evaluate(() => GSApp.crop())
  assert(c1.w === c1.h && Math.abs(c1.w - 210) <= 1 && c1.x === 105 && c1.y === 0, '拖右下角 −60 源像素：' + JSON.stringify(c1))
  assert(+(await page.$eval('#gs-cw', (e) => e.value)) === c1.w, '裁剪宽输入框应同步')
  await page.focus('#gs-cropbox'); await page.keyboard.press('ArrowRight'); await page.keyboard.press('ArrowRight')
  const c2 = await page.evaluate(() => GSApp.crop())
  assert(c2.x === c1.x + 4 && c2.w === c1.w, '方向键移动裁剪框：' + JSON.stringify(c2))
  const box = await page.evaluate(() => { const b = document.getElementById('gs-cropbox').getBoundingClientRect(), st = document.getElementById('gs-stage').getBoundingClientRect(); return { l: b.left - st.left, t: b.top - st.top, r: st.right - b.right, b: st.bottom - b.bottom } })
  assert(box.l >= -1 && box.t >= -1 && box.r >= -1 && box.b >= -1, '裁剪框应落在舞台里：' + JSON.stringify(box))
  await page.click('#gs-crop-reset')
  assert((await page.evaluate(() => GSApp.crop())).w === 480 && await page.$eval('#gs-ratio', (e) => e.value) === 'free', '重置裁剪')

  // ══ 5 我方优化 GIF（64 色）重编码：颜色不超上限 + 容差 0 ⇒ 全链路无损 ══
  await page.setInputFiles('#gs-file', { name: ORACLE.opt.file, mimeType: 'image/gif', buffer: buf(ORACLE.opt.b64) })
  await page.waitForFunction((n) => /GIF 动图 · /.test(document.getElementById('gs-src-info').textContent) && document.getElementById('gs-src-info').textContent.includes(n + ' 帧'), ORACLE.opt.frames)
  assert(await page.$eval('#gs-fps', (e) => e.value) === 'src', '动图素材默认保持源帧')
  await setVal('#gs-fuzz', 0)
  await run('#gs-encode')
  const lossless = await page.evaluate(() => {
    const L = GSApp.last(); let bad = 0
    L.frames.forEach((f, k) => { let j = 0; L.job.out.forEach((o, q) => { if (o.src <= k) j = q }); const a = L.job.intended[j]; for (let i = 0; i < a.length; i++) if (a[i] !== f.data[i]) bad++ })
    return { bad, uniq: L.job.uniqueColors, psnr: document.getElementById('gs-m-psnr').textContent, notes: document.getElementById('gs-res-notes').textContent, W: L.W, H: L.H }
  })
  const lv = await verify('gif')
  assert(lossless.W === ORACLE.opt.width && lossless.H === ORACLE.opt.height, '尺寸沿用源 ' + lossless.W + '×' + lossless.H)
  assert(lossless.uniq > 0 && lossless.uniq <= 255 && lossless.bad === 0 && lv.badPx === 0, `≤255 色素材应无损：差 ${lossless.bad} 个通道，Chromium 差 ${lv.badPx}`)
  assert(lossless.psnr === '∞ · 无损' && /颜色无损/.test(lossless.notes), 'PSNR 应显示无损：' + lossless.psnr)
  await setVal('#gs-fuzz', 3)

  // ══ 6 视频：WebM（VP9）与 MP4（H.264）帧号码 —— 抽到的每一帧都必须是该时刻的源帧 ══
  const readCodes = () => page.evaluate((code) => {
    const B = GSApp.base()
    return B.frames.map((f) => {
      let v = 0
      for (let i = 0; i < code.bits; i++) {
        let s = 0
        for (let y = 4; y < 12; y++) for (let x = 4; x < 12; x++) s += f.data[4 * ((code.y0 + y) * B.W + code.x0 + i * code.block + x)]
        if (s / 64 > 127) v |= 1 << (code.bits - 1 - i)
      }
      return v
    })
  }, ORACLE.webm.code)
  for (const fx of [ORACLE.webm, ORACLE.mp4]) {
    await page.setInputFiles('#gs-file', { name: fx.file, mimeType: fx.file.endsWith('.mp4') ? 'video/mp4' : 'video/webm', buffer: buf(fx.b64) })
    await page.waitForFunction((name) => document.getElementById('gs-src-info').textContent.includes(name) && /视频/.test(document.getElementById('gs-src-info').textContent), fx.file)
    const sv = await page.evaluate(() => ({ w: GSApp.src().w, h: GSApp.src().h, d: GSApp.src().duration, width: GSApp.settings().width }))
    assert(sv.w === fx.w && sv.h === fx.h && Math.abs(sv.d - fx.duration_s) < 0.05 && sv.width === fx.w, `${fx.file} 元数据：` + JSON.stringify(sv))
    await page.selectOption('#gs-fps', '10'); await setVal('#gs-t0', 0); await setVal('#gs-t1', 1)
    await run('#gs-encode')
    let codes = await readCodes()
    const want = Array.from({ length: 10 }, (_, k) => Math.round(k * fx.fps / 10))
    assert(JSON.stringify(codes) === JSON.stringify(want), `${fx.file} 10 fps 抽帧：${codes.join(',')}，应为 ${want.join(',')}`)
    if (fx === ORACLE.webm) {
      await page.selectOption('#gs-speed', '2')
      await run('#gs-encode')
      codes = await readCodes()
      assert(JSON.stringify(codes) === JSON.stringify([0, 6, 12, 18, 24]), '2× 速度：' + codes.join(','))
      await page.selectOption('#gs-speed', '1'); await page.selectOption('#gs-dir', 'reverse')
      await run('#gs-encode')
      codes = await readCodes()
      assert(JSON.stringify(codes) === JSON.stringify(want.slice().reverse()), '倒放：' + codes.join(','))
      await page.selectOption('#gs-dir', 'forward')
    }
  }

  // ══ 7 录屏（用 canvas.captureStream 顶替系统共享）：先测拒绝，再录 1 秒多 ══
  await page.evaluate(() => { navigator.mediaDevices.getDisplayMedia = async () => { throw new DOMException('denied', 'NotAllowedError') } })
  await page.click('#gs-rec2')
  await page.waitForFunction(() => /没有开始录屏/.test(document.getElementById('gs-status').textContent))
  await page.evaluate(() => {
    navigator.mediaDevices.getDisplayMedia = async () => {
      const c = document.createElement('canvas'); c.width = 320; c.height = 180
      const g = c.getContext('2d'); let k = 0
      const draw = () => { g.fillStyle = 'hsl(' + ((k * 7) % 360) + ',70%,45%)'; g.fillRect(0, 0, 320, 180); g.fillStyle = '#fff'; g.fillRect((k * 5) % 300, 80, 20, 20); k++; requestAnimationFrame(draw) }
      draw()
      return c.captureStream(30)
    }
  })
  await page.click('#gs-rec2')
  assert(await disp('#gs-rec-stop') !== 'none', '录制中应显示「停止录制」')
  await page.waitForFunction(() => { const m = /录制中 ([\d.]+) s/.exec(document.getElementById('gs-status').textContent); return m && +m[1] >= 1.2 }, null, { timeout: 15000 })
  await page.click('#gs-rec-stop')
  await page.waitForFunction(() => /录屏-/.test(document.getElementById('gs-src-info').textContent), null, { timeout: 20000 })
  const rec = await page.evaluate(() => ({ kind: GSApp.src().kind, d: GSApp.src().duration, w: GSApp.src().w }))
  assert(rec.kind === 'video' && rec.w === 320 && isFinite(rec.d) && rec.d > 0.8, '录屏载入为视频（时长已补算）：' + JSON.stringify(rec))
  assert(await disp('#gs-rec-stop') === 'none', '停止后「停止录制」应藏起来')

  // ══ 8 体检：ImageMagick 造的 GIF（处置 1/2/3、隔行、局部调色板、1 cs 延迟、无循环扩展）══
  await onTab('inspect')
  await page.setInputFiles('#gs-insp-file', { name: ORACLE.im.file, mimeType: 'image/gif', buffer: buf(ORACLE.im.b64) })
  await page.waitForFunction((n) => document.getElementById('gs-insp-n')?.textContent === n + ' 帧', ORACLE.im.frames)
  const pf = ORACLE.im.py_frames
  const fileMs = pf.reduce((a, f) => a + f.delay * 10, 0), effMs = pf.reduce((a, f) => a + (f.delay <= 1 ? 100 : f.delay * 10), 0), low = pf.filter((f) => f.delay <= 1).length
  assert(await txt('#gs-insp-dur') === (fileMs / 1000).toFixed(2) + ' s' && await txt('#gs-insp-effdur') === (effMs / 1000).toFixed(2) + ' s', `时长 文件 ${fileMs} / 浏览器 ${effMs}`)
  assert(ORACLE.im.chromium_repetitionCount === 0 && await txt('#gs-insp-loop') === '没有循环扩展 · 只播 1 遍', '循环：' + await txt('#gs-insp-loop'))
  const rows = await page.$$eval('#gs-insp-frames tbody tr', (trs) => trs.map((tr) => [...tr.cells].map((c) => c.textContent)))
  assert(rows.length === pf.length, '逐帧表行数')
  pf.forEach((f, i) => {
    const r = rows[i], want = [String(i + 1), `${f.rect[2]}×${f.rect[3]} @ ${f.rect[0]},${f.rect[1]}`, null, f.delay + ' cs', (f.delay <= 1 ? 100 : f.delay * 10) + ' ms', f.trans >= 0 ? String(f.trans) : '—', f.lct ? String(f.lct) : '—', f.interlace ? '是' : '否']
    want.forEach((w, j) => { if (w !== null) assert(r[j] === w, `第 ${i + 1} 帧第 ${j + 1} 列：「${r[j]}」应为「${w}」`) })
    assert(r[2].startsWith(String(f.disposal) + ' '), `第 ${i + 1} 帧处置：${r[2]}`)
  })
  const warns = await page.$$eval('#gs-insp-warn li', (ls) => ls.map((l) => [l.className, l.textContent]))
  assert(warns.filter((w) => w[0] === 'gs-w-warn').length === 2 && warns.some((w) => w[1].includes(low + ' 帧的延迟 ≤ 1 cs')) && warns.some((w) => /没有 NETSCAPE2\.0/.test(w[1])), '体检发现：' + JSON.stringify(warns))
  const sha = await page.evaluate(async (b64) => {
    const u8 = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0)), g = GS.decodeGIF(u8), out = []
    for (const f of g.decodedFrames) out.push([...new Uint8Array(await crypto.subtle.digest('SHA-1', f.data))].map((b) => b.toString(16).padStart(2, '0')).join(''))
    return out
  }, ORACLE.im.b64)
  assert(JSON.stringify(sha) === JSON.stringify(ORACLE.im.chromium_sha1), '自家解码器合成帧应与 Chromium 逐字节相同（处置 2/3 + 隔行 + 局部调色板）')
  // 手造一个「处置 3 真起作用」的 GIF：红底 → 绿帧（处置 3：画完还原成红）→ 只画中间 2×2 蓝、其余透明
  // 浏览器（ImageDecoder）当场当真值：第 3 帧四角必须是红，不是绿
  const d3 = await page.evaluate(async () => {
    const W = 4, H = 4, B = []
    const u16 = (v) => [v & 255, v >> 8]
    B.push(...[71, 73, 70, 56, 57, 97], ...u16(W), ...u16(H), 0xF1, 0, 0, 255, 0, 0, 0, 255, 0, 0, 0, 255, 0, 0, 0)
    B.push(0x21, 0xFF, 11, ...[...'NETSCAPE2.0'].map((c) => c.charCodeAt(0)), 3, 1, 0, 0, 0)
    const frame = (disp, trans, idx) => {
      B.push(0x21, 0xF9, 4, (disp << 2) | (trans >= 0 ? 1 : 0), 10, 0, trans >= 0 ? trans : 0, 0)
      B.push(0x2C, ...u16(0), ...u16(0), ...u16(W), ...u16(H), 0)
      B.push(...GS.lzwEncode(Uint8Array.from(idx), 2))
    }
    frame(1, -1, new Array(16).fill(0))
    frame(3, -1, new Array(16).fill(1))
    frame(1, 3, [3, 3, 3, 3, 3, 2, 2, 3, 3, 2, 2, 3, 3, 3, 3, 3])
    B.push(0x3B)
    const u8 = Uint8Array.from(B), own = GS.decodeGIF(u8).decodedFrames
    const dec = new ImageDecoder({ data: u8, type: 'image/gif' }); await dec.tracks.ready
    const c = document.createElement('canvas'); c.width = W; c.height = H; const g = c.getContext('2d', { willReadFrequently: true })
    let diff = 0, corner = null
    for (let j = 0; j < 3; j++) {
      const r = await dec.decode({ frameIndex: j }); g.clearRect(0, 0, W, H); g.drawImage(r.image, 0, 0); r.image.close()
      const a = g.getImageData(0, 0, W, H).data
      for (let i = 0; i < a.length; i++) if (a[i] !== own[j].data[i]) diff++
      if (j === 2) corner = [...a.slice(0, 4)]
    }
    dec.close()
    return { diff, corner, ownCorner: [...own[2].data.slice(0, 4)], center: [...own[2].data.slice(4 * 5, 4 * 5 + 4)] }
  })
  assert(d3.diff === 0 && d3.corner.join() === '255,0,0,255' && d3.ownCorner.join() === '255,0,0,255' && d3.center.join() === '0,0,255,255', '处置 3 还原：' + JSON.stringify(d3))
  await page.setInputFiles('#gs-insp-file', { name: ORACLE.cmt.file, mimeType: 'image/gif', buffer: buf(ORACLE.cmt.b64) })
  await page.waitForFunction((n) => document.getElementById('gs-insp-n')?.textContent === n + ' 帧', ORACLE.cmt.frames)
  assert((await txt('#gs-insp-warn')).includes(ORACLE.cmt.comments + ' 段注释扩展'), '注释扩展应被报出来')
  await page.setInputFiles('#gs-insp-file', { name: ORACLE.im.file, mimeType: 'image/gif', buffer: buf(ORACLE.im.b64) })
  await page.waitForFunction((n) => document.getElementById('gs-insp-n')?.textContent === n + ' 帧', ORACLE.im.frames)
  await page.click('#gs-insp-send')
  await page.waitForFunction((n) => !document.getElementById('pane-make').hidden && document.getElementById('gs-src-info').textContent.includes('GIF 动图 · ' + n + ' 帧'), ORACLE.im.frames)

  // ══ 9 体积预算：Slack 128 KB / ≤50 帧 ══
  await page.click('#gs-demo-dusk2')
  await page.selectOption('#gs-budget-preset', 'slack')
  assert(await page.$eval('#gs-budget-kb', (e) => e.value) === '128' && /128,000 字节/.test(await txt('#gs-budget-bytes')), 'Slack 预设 128 KB')
  await run('#gs-solve')
  const sol = await page.evaluate(() => {
    const L = GSApp.last(), rows = [...document.querySelectorAll('#gs-solve-log tbody tr')]
    return { bytes: L.bytes.length, n: L.job.out.length, rows: rows.length, best: rows.filter((r) => r.classList.contains('gs-best')).map((r) => [+r.cells[1].textContent, r.cells[5].textContent]),
      feas: rows.filter((r) => r.cells[6].textContent === '装得下').map((r) => +r.cells[1].textContent), shown: document.getElementById('gs-res-size').textContent, status: document.getElementById('gs-status').textContent }
  })
  assert(sol.bytes <= 128000 && sol.n <= 50, `求解结果 ${sol.bytes} 字节 / ${sol.n} 帧`)
  assert(sol.rows >= 2 && sol.best.length === 1 && sol.best[0][1] === sol.shown, '求解日志：' + JSON.stringify(sol))
  assert(sol.feas.every((l) => l >= sol.best[0][0]), '选中的应是装得下的里压缩档最小的那个')
  const sv2 = await verify('gif')
  assert(sv2.badPx === 0, `求解结果（缩放 + 重定帧率后）浏览器解码仍应等于预期：${sv2.badPx}`)
  await page.click('#gs-budget-side')
  assert(/输出 128 × 128/.test(await txt('#gs-outdim')), '套用建议 128 × 128：' + await txt('#gs-outdim'))
  await page.click('#gs-crop-reset')
  await page.selectOption('#gs-budget-preset', 'github')

  // ══ 10 记录、预设、离页立刻持久化 ══
  await onTab('history')
  const hist = await page.evaluate(() => ({ rows: document.querySelectorAll('#gs-hist-table tbody tr button').length, n: document.getElementById('gs-hist-n').textContent, first: document.querySelector('#gs-hist-table tbody tr').cells[6].textContent }))
  assert(hist.rows === Math.min(40, encodes) && hist.n === hist.rows + ' 条', `记录 ${hist.rows} 条（编码 ${encodes} 次）`)
  assert(hist.first === sol.shown, '最新一条记录的体积 = 刚才的结果')
  await page.fill('#gs-preset-name', '测试预设')
  await page.click('#gs-preset-save')
  assert((await txt('#gs-preset-list')).includes('测试预设'), '预设已保存')
  await onTab('make')
  await setVal('#gs-colors', 77)
  await onTab('history')
  await page.click('#gs-preset-list button[data-pi="0"]')
  assert(await page.$eval('#gs-colors', (e) => e.value) === '256' && !(await page.$eval('#pane-make', (e) => e.hidden)), '套用预设后颜色数回到 256')
  await setVal('#gs-colors', 77)
  await setVal('#gs-fuzz', 5)
  await page.reload()
  assert(await page.$eval('#gs-colors', (e) => e.value) === '77' && await page.$eval('#gs-fuzz', (e) => e.value) === '5', '改完立刻刷新，设置应已写盘（pagehide 补写）')
  await onTab('history')
  assert(await page.$$eval('#gs-hist-table tbody tr button', (b) => b.length) === Math.min(40, encodes), '刷新后记录仍在')
  await onTab('make')
  await setVal('#gs-colors', 256); await setVal('#gs-fuzz', 3)

  // ══ 11 渲染守卫（结果、对比、体检表都渲染出来之后再扫）══
  await page.click('#gs-demo-dusk')
  await run('#gs-encode')
  await onTab('inspect')
  await page.click('#gs-insp-last')
  await page.waitForFunction(() => document.getElementById('gs-insp-n')?.textContent === '45 帧')
  await onTab('make')
  await page.click('#gs-view-cmp')
  await page.waitForFunction(() => +(document.getElementById('gs-cmp-diff').getAttribute('data-psnr') || 0) > 0)
  await guardHidden(page, { assert, panesRoot: '#gs-panes', tabs: T })
  await guardUniqueIds(page, { assert, minIds: 120 })
  const nc = await guardControlSize(page, { assert, tabs: T, onTab, paneSel: (t) => '#pane-' + t, minControls: 50 })
  assert(nc >= 50, '逐页签扫到的可见控件 ' + nc)
  await guardTextTransform(page, { assert, tabs: T, onTab, paneSel: (t) => '#pane-' + t })
  await guardEscape(page, { assert, cardSel: '.gs-sec, .gs-panel, .gs-metric, .gs-chartbox', childSel: 'svg,table,dl,h2,h3,p,input,select,button' })
  await guardFigText(page, { assert, tabs: ['make'], onTab, figSel: () => '#gs-res-chart', minTextsInFig: 8 })
  await guardOverflow(page, { assert, tabs: T, onTab, panesRoot: '#gs-panes', viewports: [390, 768] })
  await onTab('make')
  const diffShown = await page.evaluate(() => { const c = document.getElementById('gs-cmp-diff'), r = c.getBoundingClientRect(); return r.width > 50 && r.height > 20 })
  assert(diffShown, '对比视图的差异图应真的显示出来（几何）')

  // ══ 缩略图：输出视图、页面顶部 ══
  await page.click('#gs-view-out')
  await page.evaluate(() => window.scrollTo(0, 0))
  await page.waitForFunction(() => { const i = document.getElementById('gs-out-img'); return i.complete && i.naturalWidth === 480 && getComputedStyle(i).display !== 'none' })
  await screenshot('thumb.png')
}
